<?php
namespace App\Http\Controllers\Client;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class SupportController extends Controller {
 public function index(Request $r){$tickets=DB::table('support_tickets')->where('user_id',$r->user()->id)->latest('last_message_at')->paginate(15);return view('client.support.index',['tickets'=>$tickets,'ticket'=>null,'messages'=>collect()]);}
 public function show(Request $r,int $ticket){$record=DB::table('support_tickets')->where('id',$ticket)->where('user_id',$r->user()->id)->first();abort_unless($record,404);$tickets=DB::table('support_tickets')->where('user_id',$r->user()->id)->latest('last_message_at')->paginate(15);$messages=DB::table('support_messages')->leftJoin('users','users.id','=','support_messages.user_id')->where('support_ticket_id',$record->id)->select('support_messages.*','users.name as sender_name')->orderBy('support_messages.created_at')->get();return view('client.support.index',compact('tickets','record','messages')+['ticket'=>$record]);}
 public function store(Request $r){$v=$r->validate(['subject'=>['required','string','min:5','max:140'],'category'=>['required','in:account,trading,market_data,security,other'],'message'=>['required','string','min:10','max:5000']]);$id=DB::transaction(function()use($r,$v){$now=now();$id=DB::table('support_tickets')->insertGetId(['user_id'=>$r->user()->id,'subject'=>$v['subject'],'category'=>$v['category'],'status'=>'open','last_message_at'=>$now,'created_at'=>$now,'updated_at'=>$now]);DB::table('support_messages')->insert(['support_ticket_id'=>$id,'user_id'=>$r->user()->id,'sender_role'=>'client','message'=>$v['message'],'created_at'=>$now,'updated_at'=>$now]);return $id;});return redirect()->route('support.show',$id)->with('status','Support ticket created.');}
 public function reply(Request $r,int $ticket){$v=$r->validate(['message'=>['required','string','min:2','max:5000']]);$record=DB::table('support_tickets')->where('id',$ticket)->where('user_id',$r->user()->id)->first();abort_unless($record,404);abort_if($record->status==='closed',409,'This ticket is closed. Create a new ticket if you need further help.');DB::transaction(function()use($r,$v,$record){$now=now();DB::table('support_messages')->insert(['support_ticket_id'=>$record->id,'user_id'=>$r->user()->id,'sender_role'=>'client','message'=>$v['message'],'created_at'=>$now,'updated_at'=>$now]);DB::table('support_tickets')->where('id',$record->id)->update(['status'=>'pending','last_message_at'=>$now,'updated_at'=>$now]);});return redirect()->route('support.show',$record->id)->with('status','Reply sent.');}
}